import {initialState,applyOperation,validateState,money,quantity,numberInput,saleAccounting,saleRefundSummary,accountingSummary} from './domain.mjs';
import {selectStorage,readLocal,changeLocal,initializePrimary,localOperation,markUploaded,restoreEmptyBackup} from './storage.mjs';
import {storeProfiles,defaultStoreId,getStoreProfile} from './profiles.mjs';
import {createDemoCatalog,createDemoSales,isLegacyDemo,demoFixtureNeedsShopName} from './demo-fixtures.mjs';
import {buildSaleData} from './sale-data.mjs';
import {renderSaleView} from './sales-view.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const query=new URLSearchParams(location.search);
const forceMobile=query.get('consulta')==='1';
const demo=query.get('demo')==='1';
const requestedStore=query.get('store')||localStorage.getItem('mi-tienda-active-store')||defaultStoreId;
const storeProfile=getStoreProfile(requestedStore)||getStoreProfile(defaultStoreId);
const storeId=storeProfile.id;
localStorage.setItem('mi-tienda-active-store',storeId);
selectStorage(`${demo?'demo':'primary'}:${storeId}`);
const pendingStorageKey=`mi-tienda-pending-sale:${storeId}`;
if(storeId===defaultStoreId&&!localStorage.getItem(pendingStorageKey)&&localStorage.getItem('mi-tienda-pending-sale'))localStorage.setItem(pendingStorageKey,localStorage.getItem('mi-tienda-pending-sale'));
let state=initialState(),local=null,ownerId='',cloud=null,role='none',view='dashboard',search='',filter='all',page=0,cart=[],busy=false,ticking=false,available=false,lastError='',swReady=false,reportFrom='',reportTo='';
let deviceId=localStorage.getItem('mi-tienda-device')||crypto.randomUUID();localStorage.setItem('mi-tienda-device',deviceId);
const mobile=/Android|iPhone|iPad|iPod/i.test(navigator.userAgent);
let saleDraft={documentType:'sale',customer:'',customerPhone:'',customerIdNumber:'',paid:'',method:'Efectivo'};
let pendingSale=null;try{pendingSale=JSON.parse(localStorage.getItem(pendingStorageKey)||'null');}catch{}
const at=s=>new Date(s).toLocaleString('es-DO',{timeZone:'America/Santo_Domingo',dateStyle:'short',timeStyle:'short'});
const day=s=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Santo_Domingo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(s));
const primary=()=>role==='primary'||demo;
const newOp=(kind,data)=>({id:crypto.randomUUID(),at:new Date().toISOString(),kind,data,source:'PC'});
function toast(message,bad=false){$('#toast').textContent=message;$('#toast').classList.toggle('bad',bad);$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,6000);}
async function api(action,data={}){const url=`/api/inventory?storeId=${encodeURIComponent(storeId)}`;const options=action?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,storeId,...data})}:{cache:'no-store'};const r=await fetch(url,options);let j;try{j=await r.json();}catch{throw Error('El servidor no respondió. Las operaciones de la PC siguen guardadas localmente.');}if(!r.ok){const e=Error(j.error||'No se pudo conectar.');e.status=r.status;throw e;}return j;}
async function commit(kind,data){if(!primary())throw Error('Los cambios de inventario se hacen desde la PC principal.');local=await localOperation(newOp(kind,data));state=local.state;render();void tick();}
function go(next){view=next;search='';filter='all';page=0;$('.sidebar').classList.remove('open');render();}
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.view)));
$('#menu-toggle').onclick=()=>$('.sidebar').classList.toggle('open');$('#sync-btn').onclick=()=>{void tick(true);};
$('#store-select').innerHTML=storeProfiles.map(p=>`<option value="${p.id}" ${p.id===storeId?'selected':''}>${esc(p.name)}</option>`).join('');
$('#store-select').onchange=()=>{const next=$('#store-select').value;if(!getStoreProfile(next))return;localStorage.setItem('mi-tienda-active-store',next);const params=new URLSearchParams({store:next});if(demo)params.set('demo','1');if(forceMobile)params.set('consulta','1');location.assign(`/caja/index.html?${params}`);};
function heading(title,subtitle,buttons=''){return `<div class="page-heading"><div><div class="eyebrow">TU NEGOCIO, EN ORDEN</div><h1>${title}</h1><p>${subtitle}</p></div><div class="actions">${buttons}</div></div>`;}
function btn(label,action,classes='',disabled=false){return `<button class="btn ${classes}" data-action="${action}" ${disabled?'disabled':''}>${label}</button>`;}
function empty(title,description,action='',label=''){return `<div class="empty"><span class="symbol">▤</span><h3>${title}</h3><p>${description}</p>${action?btn(label,action,'primary'):''}</div>`;}
function stockBadge(p){return p.stock===0?'<span class="badge out">Agotado</span>':p.stock<=p.minStock?'<span class="badge low">Existencia baja</span>':'<span class="badge">Disponible</span>';}
function stats(){const active=state.products.filter(p=>p.active),today=accountingSummary(state,day(Date.now()),day(Date.now())),low=active.filter(p=>p.stock<=p.minStock),cost=active.reduce((n,p)=>n+Math.round(p.costCents*p.stock/1000),0);return {active,today,low,cost};}
function status(){
 $('#shop-name').textContent=state.shop.name==='Mi tienda'?storeProfile.name:state.shop.name;$('#device-label').textContent=demo?'Demostración en este equipo':role==='primary'?'PC principal':role==='mobile'?'Celular / consulta':'Configurar equipo';
 const badge=$('#connection');badge.className='status';
 if(demo){badge.textContent='Demostración';badge.classList.add('offline');}
 else if(lastError){badge.textContent=lastError.includes('sesión')?'Inicia sesión':primary()?'PC sin conexión':'Consulta sin actualizar';badge.classList.add('offline');}
 else if(primary()){const n=Math.max(0,state.version-(local?.uploadedVersion??-1));badge.textContent=n?`${n} cambio${n===1?'':'s'} pendiente${n===1?'':'s'}`:'Sincronizado';if(n)badge.classList.add('offline');}
 else{badge.textContent=available?'PC conectada':'PC desconectada';if(!available)badge.classList.add('offline');}
 $('#last-sync').textContent=demo?'Datos de ejemplo · separados de tu tienda':local?.lastSync?`Última sincronización: ${at(local.lastSync)}`:cloud?.updatedAt?`Última información: ${at(cloud.updatedAt)}`:'Todavía sin sincronizar';
}
function notice(){let n='';if(demo)n+=`<div class="notice">Estás probando una tienda de ejemplo. Sus datos se guardan separados de tu inventario real. <a href="/caja/index.html">Ir a mi tienda →</a></div>`;else if(!primary()&&!available)n+='<div class="notice">La PC principal no está disponible. Puedes consultar la última información recibida. Las ventas del celular están bloqueadas.</div>';if(primary()&&!swReady)n+='<div class="notice">Preparando el acceso sin internet… Mantén abierta la aplicación hasta que termine.</div>';if(primary()&&lastError&&!demo)n+=`<div class="notice">${esc(lastError)} <a href="/login">Revisar mi acceso</a></div>`;return n;}
function onboarding(){return `${lastError?'<div class="notice">'+esc(lastError)+'</div>':''}<section class="onboarding"><span class="brand-mark">m.</span><div class="eyebrow">BIENVENIDO A MI TIENDA</div><h1>Todo tu inventario.<br>Una sola caja principal.</h1><p>Registra artículos, entradas y ventas. La computadora guarda cada movimiento y puede seguir trabajando cuando falte internet.</p>${ownerId?cloud?'<div class="notice green">Esta tienda ya tiene una PC principal. En este equipo puedes consultar y vender cuando la PC confirme la operación.</div>':'<p>Configura la computadora de caja como PC principal. En el celular, entra después con tu misma cuenta.</p>':'<p>Entra a tu cuenta para preparar tu tienda. También puedes explorar una demostración con artículos de ejemplo.</p>'}<div class="actions">${ownerId&&!cloud?btn('Configurar esta PC como principal','register','primary',mobile):''}${ownerId&&cloud?btn('Abrir como celular / consulta','mobile','primary'):''}${!ownerId?'<a class="btn primary" href="/login">Entrar a mi cuenta</a>':''}<a class="btn" href="/caja/index.html?demo=1">Probar demostración</a></div>${mobile&&!cloud&&ownerId?'<p class="setup-note">La primera configuración debe hacerse desde la computadora de caja.</p>':''}<div class="file-zone"><strong>¿Tienes un respaldo de esta tienda?</strong><p>Recupéralo en una instalación vacía antes de trabajar.</p>${btn('Recuperar respaldo','restore','',!ownerId)}</div></section>`;}
function dashboard(){const {active,today,low,cost}=stats();return heading('Tu tienda, de un vistazo','Existencias, facturas y dinero conciliados por fecha.',btn('＋ Vender','sale','primary'))+`<div class="metrics"><article class="metric"><span>Artículos activos <b>▤</b></span><strong>${active.length.toLocaleString('es-DO')}</strong><small>Productos en tu catálogo</small></article><article class="metric dark"><span>Venta neta de hoy <b>↗</b></span><strong>${money(today.netSalesCents)}</strong><small>${today.saleCount} comprobante${today.saleCount===1?'':'s'} emitido${today.saleCount===1?'':'s'}</small></article><article class="metric"><span>Caja neta de hoy <b>▣</b></span><strong>${money(today.netCashCents)}</strong><small>Cobros menos devoluciones pagadas</small></article><article class="metric"><span>Existencia baja <b>◉</b></span><strong>${low.length}</strong><small>${money(cost)} al costo registrado</small></article></div><div class="grid"><div><section class="card"><div class="card-head"><div><h2>Últimas ventas y facturas</h2><p>Importe neto y saldo por cobrar</p></div>${btn('Ver todas →','sales','link')}</div>${state.sales.length?state.sales.slice(-5).reverse().map(s=>{const f=saleAccounting(s,state);return `<div class="list-row"><div><strong>${esc(s.number)}</strong><small>${esc(s.customer)} · ${at(s.at)}</small></div><div class="numeric"><strong>${money(f.netRevenueCents)}</strong><small>${f.status}${f.balanceCents?` · saldo ${money(f.balanceCents)}`:''}</small></div>${btn('Ver',`receipt:${s.id}`,'link')}</div>`;}).join(''):empty('Tu primera venta comienza aquí','Las ventas y facturas se guardan como comprobantes internos y descuentan existencias.','sale','Crear factura')}</section><section class="card"><div class="card-head"><div><h2>Accesos rápidos</h2><p>Lo que haces cada día</p></div></div><div class="card-body quick-actions"><button class="quick-action" data-action="product"><span>＋</span><strong>Registrar artículo</strong><small>Nombre, código, precio y existencia inicial.</small></button><button class="quick-action" data-action="movement"><span>⇄</span><strong>Entrada de mercancía</strong><small>Agrega lo que recibes y conserva la referencia.</small></button></div></section></div><section class="card"><div class="card-head"><div><h2>Para reponer</h2><p>En el mínimo o por debajo</p></div><span class="badge low">${low.length} artículos</span></div>${low.length?low.slice(0,8).map(p=>`<div class="list-row"><div class="product-cell"><span class="product-icon">▣</span><div><strong>${esc(p.name)}</strong><small>${esc(p.sku)}</small></div></div><div class="numeric"><strong>${quantity(p.stock)}</strong><small>Mínimo: ${quantity(p.minStock)}</small></div></div>`).join(''):empty(active.length?'Todo en orden':'Aún no hay artículos',active.length?'Tus artículos están por encima del mínimo.':'Agrega productos para comenzar a controlar tus existencias.')}</section></div>`;}
function productRows(products){return products.map(p=>`<tr><td><div class="product-cell"><span class="product-icon">▣</span><div><strong>${esc(p.name)}</strong><small>${esc(p.sku)}${p.barcode?' · '+esc(p.barcode):''}</small></div></div></td><td>${esc(p.category||'Sin categoría')}</td><td class="numeric">${money(p.unitCents)}</td><td class="numeric"><strong>${quantity(p.stock)}</strong><small>Mín. ${quantity(p.minStock)}</small></td><td>${p.active?stockBadge(p):'<span class="badge muted">Inactivo</span>'}</td><td class="numeric">${btn('Editar',`edit:${p.id}`,'link',!primary())}${btn('⇄',`move:${p.id}`,'link',!primary())}</td></tr>`).join('');}
function filtered(){const q=search.toLocaleLowerCase();return state.products.filter(p=>(`${p.name} ${p.sku} ${p.barcode} ${p.category}`).toLocaleLowerCase().includes(q)&&(filter==='all'||filter==='low'&&p.active&&p.stock<=p.minStock||filter==='active'&&p.active||filter==='inactive'&&!p.active)).sort((a,b)=>a.name.localeCompare(b.name,'es'));}
function inventory(){const all=filtered();page=Math.min(page,Math.max(0,Math.ceil(all.length/50)-1));return heading('Inventario','Busca por nombre, código o código de barras.',btn('↑ Importar CSV','import','',!primary())+btn('＋ Nuevo artículo','product','primary',!primary()))+`<section class="card"><div class="toolbar"><div class="search"><input id="inventory-search" aria-label="Buscar artículos" placeholder="Buscar entre ${state.products.length} artículos…" value="${esc(search)}"></div><div class="filter"><select id="stock-filter" aria-label="Filtrar existencias"><option value="all" ${filter==='all'?'selected':''}>Todos los artículos</option><option value="low" ${filter==='low'?'selected':''}>Existencia baja / agotados</option><option value="active" ${filter==='active'?'selected':''}>Solo activos</option><option value="inactive" ${filter==='inactive'?'selected':''}>Inactivos</option></select>${btn('↓ Exportar','export','small')}</div></div>${all.length?`<div class="table-scroll"><table><thead><tr><th>Artículo</th><th>Categoría</th><th class="numeric">Precio de venta</th><th class="numeric">Existencia</th><th>Estado</th><th></th></tr></thead><tbody>${productRows(all.slice(page*50,page*50+50))}</tbody></table></div><div class="pagination"><span>${page*50+1}–${Math.min(page*50+50,all.length)} de ${all.length} artículos</span><div class="actions">${btn('←','prev','small',page===0)}${btn('→','next','small',(page+1)*50>=all.length)}</div></div>`:empty(state.products.length?'No hay coincidencias':'Tu inventario empieza aquí',state.products.length?'Prueba con otro nombre o código.':'Agrega un artículo o importa tu catálogo desde un archivo CSV.',state.products.length?'':'product','Registrar artículo')}</section>`;}
function cartTotal(){return cart.reduce((n,c)=>{const p=state.products.find(p=>p.id===c.productId);return n+Math.round((p?.unitCents||0)*c.quantity/1000)},0);}
function saleView(){return renderSaleView({state,search,cart,page,saleDraft,primary:primary(),available,busy,pendingSale,money,quantity,esc,cartTotal,heading,btn});}
function salesView(){const summary=accountingSummary(state,reportFrom,reportTo),list=state.sales.filter(s=>{const key=day(s.at);return `${s.number} ${s.customer} ${s.customerIdNumber||''}`.toLowerCase().includes(search.toLowerCase())&&(!reportFrom||key>=reportFrom)&&(!reportTo||key<=reportTo);}).slice().reverse();return heading('Ventas y facturas','Revisa cobros, saldos, devoluciones y el resultado del período.',btn('↓ Exportar libro','accounting-export','')+btn('＋ Vender','sale','primary'))+`<div class="metrics accounting-metrics"><article class="metric"><span>Venta bruta</span><strong>${money(summary.grossSalesCents)}</strong><small>${summary.saleCount} comprobantes internos emitidos</small></article><article class="metric"><span>Devoluciones</span><strong>${money(summary.refundCents)}</strong><small>Importe devuelto de facturas</small></article><article class="metric dark"><span>Venta neta</span><strong>${money(summary.netSalesCents)}</strong><small>Bruto menos devoluciones</small></article><article class="metric"><span>Caja neta</span><strong>${money(summary.netCashCents)}</strong><small>Cobrado menos dinero reembolsado</small></article><article class="metric"><span>Por cobrar</span><strong>${money(summary.receivableCents)}</strong><small>Saldo pendiente al cierre</small></article><article class="metric"><span>Utilidad bruta estimada</span><strong>${money(summary.grossProfitCents)}</strong><small>Venta neta menos costo de mercancía</small></article></div><p class="receipt-note accounting-note">Esta vista es un control gerencial interno; no incorpora impuestos ni sustituye los libros o comprobantes fiscales.</p><section class="card"><div class="toolbar accounting-toolbar"><div class="search"><input id="sales-search" aria-label="Buscar ventas y facturas" placeholder="Número, cliente o cédula/RNC…" value="${esc(search)}"></div><label>Desde<input id="report-from" type="date" value="${esc(reportFrom)}" max="${esc(reportTo||'')}" aria-label="Período desde"></label><label>Hasta<input id="report-to" type="date" value="${esc(reportTo)}" min="${esc(reportFrom||'')}" aria-label="Período hasta"></label><small>${list.length} facturas en la lista</small></div>${list.length?`<div class="table-scroll"><table><thead><tr><th>Documento interno</th><th>Cliente</th><th>Fecha</th><th>Estado</th><th class="numeric">Total neto</th><th class="numeric">Saldo</th><th></th></tr></thead><tbody>${list.slice(page*50,page*50+50).map(s=>{const f=saleAccounting(s,state);return `<tr><td><strong>${esc(s.number)}</strong><small>${s.documentType==='sale'?'Venta normal':'Factura a nombre de cliente'}</small></td><td><strong>${esc(s.customer)}</strong><small>${esc(s.customerIdNumber||s.customerPhone||'')}</small></td><td>${at(s.at)}</td><td><span class="badge ${f.status==='Devuelta'?'out':f.balanceCents?'low':''}">${esc(f.status)}</span></td><td class="numeric">${money(f.netRevenueCents)}</td><td class="numeric">${money(f.balanceCents)}</td><td class="invoice-row-actions">${f.balanceCents>0&&primary()?btn('Cobrar',`collect:${s.id}`,'small'):''}${!f.returnedAll&&primary()?btn('Devolver',`refund:${s.id}`,'small'):''}${btn('Ver comprobante',`receipt:${s.id}`,'link')}</td></tr>`;}).join('')}</tbody></table></div>${pager(list.length)}`:empty('No hay ventas ni facturas en este período','Ajusta las fechas o registra una venta.','sale','Crear factura')}</section>`;}
function pager(n){return `<div class="pagination"><span>${Math.min(n,page*50+1)}–${Math.min(n,page*50+50)} de ${n}</span><div class="actions">${btn('←','prev','small',!page)}${btn('→','next','small',(page+1)*50>=n)}</div></div>`;}
function movementsView(){const list=state.movements.filter(m=>`${m.name} ${m.sku} ${m.note}`.toLowerCase().includes(search.toLowerCase())).slice().reverse();return heading('Movimientos','Entradas, ventas y ajustes, con su motivo y existencia resultante.',btn('＋ Registrar movimiento','movement','primary',!primary()))+`<section class="card"><div class="toolbar"><div class="search"><input id="movements-search" aria-label="Buscar movimientos" placeholder="Buscar artículo o referencia…" value="${esc(search)}"></div><small>${list.length} movimientos</small></div>${list.length?`<div class="table-scroll"><table><thead><tr><th>Fecha</th><th>Artículo</th><th>Movimiento</th><th class="numeric">Cantidad</th><th class="numeric">Existencia después</th><th>Referencia</th></tr></thead><tbody>${list.slice(page*50,page*50+50).map(m=>`<tr><td>${at(m.at)}</td><td><strong>${esc(m.name)}</strong><small>${esc(m.sku)}</small></td><td>${esc(m.kind)}</td><td class="numeric">${m.delta>0?'+':''}${quantity(m.delta)}</td><td class="numeric">${quantity(m.stockAfter)}</td><td>${esc(m.note)}</td></tr>`).join('')}</tbody></table></div>${pager(list.length)}`:empty('Sin movimientos todavía','Las existencias iniciales y cada cambio quedarán registrados aquí.')}</section>`;}
function field(label,name,value='',type='text',extra=''){return `<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;}
function settingsView(){return heading('Mi tienda','Datos del negocio, respaldo y funcionamiento de la caja.')+`<div class="grid"><section class="card"><div class="card-head"><h2>Datos de tu negocio</h2></div><form id="settings-form" class="card-body"><div class="form-grid">${field('Nombre de la tienda','name',state.shop.name,'text','required maxlength="160"')}${field('RNC (opcional)','rnc',state.shop.rnc,'text','maxlength="40"')}${field('Teléfono','phone',state.shop.phone,'text','maxlength="40"')}${field('Dirección','address',state.shop.address,'text','maxlength="300"')}</div><div class="modal-actions"><button class="btn primary" ${!primary()?'disabled':''}>Guardar datos</button></div></form></section><div><section class="card"><div class="card-head"><h2>Respaldo de la tienda</h2></div><div class="card-body"><p class="setup-note">Descarga un respaldo al cerrar la jornada y guárdalo fuera de esta computadora. Incluye catálogo, movimientos y comprobantes.</p><div class="actions">${btn('↓ Descargar respaldo','backup','primary',!primary())}${btn('Recuperar respaldo','restore','',!primary())}</div><p class="setup-note">Último respaldo: ${local?.backupAt?at(local.backupAt):'Todavía no descargado'}</p></div></section><section class="card"><div class="card-head"><h2>Este equipo</h2></div><div class="card-body"><div class="stat-band"><div><small>Función</small><strong>${demo?'Demostración':primary()?'PC principal':'Celular / consulta'}</strong></div><div><small>Acceso sin internet</small><strong>${swReady?'Aplicación preparada':'Preparando'}</strong></div></div><p class="setup-note">Usa la misma cuenta en el celular. La PC debe estar encendida, con la aplicación abierta y conectada para confirmar ventas del celular.</p><p class="setup-note">Si cierras esta aplicación, la sincronización se reanuda cuando vuelvas a abrirla. No borres los datos del navegador con operaciones pendientes.</p><div class="actions"><a class="btn" href="/login">Acceso a la cuenta ↗</a><a class="btn" href="/caja/index.html?consulta=1" target="_blank" rel="noopener">Vista del celular ↗</a></div></div></section></div></div>`;}
function render(){const existing=$('#sale-form');if(existing)saleDraft={...saleDraft,...Object.fromEntries(new FormData(existing))};status();const titles={dashboard:'Resumen',inventory:'Inventario',sale:'Vender',sales:'Ventas y facturas',movements:'Movimientos',settings:'Mi tienda'};$('#breadcrumb').textContent=titles[view];document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#main').innerHTML=role==='none'?onboarding():notice()+({dashboard,inventory,sale:saleView,sales:salesView,movements:movementsView,settings:settingsView}[view])();bindView();if($('#sale-form'))for(const key of ['customer','customerPhone','customerIdNumber','paid','method'])if($('#sale-form [name='+key+']'))$('#sale-form [name='+key+']').value=saleDraft[key]||(key==='method'?'Efectivo':'');}
function bindView(){
 $('#main').querySelectorAll('[data-action]').forEach(button=>button.onclick=()=>void action(button.dataset.action));
 for(const id of ['inventory-search','sale-search','sales-search','movements-search']){const input=$('#'+id);if(input)input.oninput=()=>{const pos=input.selectionStart;search=input.value;page=0;render();const newer=$('#'+id);newer.focus();newer.setSelectionRange(pos,pos);};}
 if($('#report-from'))$('#report-from').onchange=event=>{reportFrom=event.target.value;page=0;render();};
 if($('#report-to'))$('#report-to').onchange=event=>{reportTo=event.target.value;page=0;render();};
 if($('#sale-search'))$('#sale-search').onkeydown=event=>{if(event.key==='Enter'){event.preventDefault();const product=state.products.find(item=>item.active&&(item.barcode===search||item.sku===search));if(product){add(product.id);search='';render();$('#sale-search').focus();}}};
 if($('#stock-filter'))$('#stock-filter').onchange=event=>{filter=event.target.value;page=0;render();};
 document.querySelectorAll('[data-cart]').forEach(input=>{input.oninput=()=>{try{const amount=numberInput(input.value,1000);if(!amount)throw Error('La cantidad debe ser mayor que cero.');const product=state.products.find(item=>item.id===input.dataset.cart);if(amount>product.stock)throw Error('No hay esa cantidad disponible.');input.setCustomValidity('');cart.find(item=>item.productId===product.id).quantity=amount;input.closest('.cart-line').querySelector('small').textContent=money(product.unitCents)+' · '+money(Math.round(product.unitCents*amount/1000));$('.totals strong').textContent=money(cartTotal());$('#paid').placeholder=(cartTotal()/100).toFixed(2);$('#sale-form button[type=submit]').textContent='Emitir factura interna · '+money(cartTotal());}catch(error){input.setCustomValidity(error.message);}};input.onchange=input.oninput;});
 if($('#sale-document-type'))$('#sale-document-type').onchange=()=>{saleDraft={...saleDraft,...Object.fromEntries(new FormData($('#sale-form')))};render();};
  if($('#sale-form'))$('#sale-form').onsubmit=submitSale;
 if($('#settings-form'))$('#settings-form').onsubmit=async event=>{event.preventDefault();try{await commit('settings',Object.fromEntries(new FormData(event.target)));toast('Datos de la tienda guardados.');}catch(error){toast(error.message,true);}};
}
function add(id){const p=state.products.find(p=>p.id===id),c=cart.find(c=>c.productId===id),next=(c?.quantity||0)+1000;if(next>p.stock){toast('No hay más unidades disponibles.',true);return;}if(c)c.quantity=next;else cart.push({productId:id,quantity:1000});render();}
async function action(actionId){try{const [kind,id]=actionId.split(':');if(['product','edit','movement','move','import','collect','refund'].includes(kind)&&!primary())throw Error('Haz este cambio desde la PC principal.');if(kind==='register'){await api('register',{deviceId});local=await initializePrimary(ownerId,deviceId,storeProfile.name);state=local.state;role='primary';render();await tick(true);await navigator.storage?.persist?.();}else if(kind==='mobile'){role='mobile';state=cloud?.state||state;render();}else if(kind==='product'||kind==='edit')productModal(id);else if(kind==='movement'||kind==='move')movementModal(id);else if(kind==='add')add(id);else if(kind==='remove'){cart=cart.filter(item=>item.productId!==id);render();}else if(kind==='prev'||kind==='next'){page=Math.max(0,page+(kind==='next'?1:-1));render();}else if(kind==='receipt')receiptModal(id);else if(kind==='collect')collectionModal(id);else if(kind==='refund')refundModal(id);else if(kind==='backup')await backup();else if(kind==='restore')$('#restore-file').click();else if(kind==='export')exportCsv();else if(kind==='accounting-export')exportAccountingCsv();else if(kind==='import')importModal();else if(kind==='void')voidModal(id);else go(kind);}catch(error){toast(error.message,true);}}
function modal(title,body){$('#modal-body').innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="close" aria-label="Cerrar">×</button></div><div id="form-error" hidden class="error-text" role="alert"></div>${body}`;$('#modal .close').onclick=()=>$('#modal').close();$('#modal').showModal();}
function formError(e){$('#form-error').textContent=e.message;$('#form-error').hidden=false;}
function productModal(id){const p=state.products.find(p=>p.id===id);modal(p?'Editar artículo':'Nuevo artículo',`<form id="product-form"><div class="form-grid">${field('Nombre del artículo','name',p?.name||'','text','required maxlength="160"')}${field('Código único / SKU','sku',p?.sku||'','text','required maxlength="80"')}${field('Código de barras (opcional)','barcode',p?.barcode||'','text','maxlength="80"')}${field('Categoría','category',p?.category||'','text','maxlength="80"')}${field('Precio de venta · RD$','price',p?(p.unitCents/100).toFixed(2):'','text','inputmode="decimal" required')}${field('Costo unitario · RD$','cost',p?(p.costCents/100).toFixed(2):'0','text','inputmode="decimal" required')}${!p?field('Existencia inicial','stock','0','text','inputmode="decimal" required'):'<div class="field"><label>Existencia actual</label><div class="stat-band">'+quantity(p.stock)+'<small>Usa un movimiento para modificarla.</small></div></div>'}${field('Existencia mínima','minStock',p?p.minStock/1000:'0','text','inputmode="decimal" required')}${p?'<div class="field"><label for="active">Estado</label><select id="active" name="active"><option value="true" '+(p.active?'selected':'')+'>Activo</option><option value="false" '+(!p.active?'selected':'')+'>Inactivo</option></select></div>':''}</div><div class="modal-actions"><button class="btn primary">Guardar artículo</button></div></form>`);$('#product-form').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));try{await commit('product',{id:p?.id,name:f.name,sku:f.sku,barcode:f.barcode,category:f.category,unitCents:numberInput(f.price),costCents:numberInput(f.cost),stock:p?0:numberInput(f.stock,1000),minStock:numberInput(f.minStock,1000),active:f.active!=='false'});$('#modal').close();toast('Artículo guardado.');}catch(e){formError(e);}};}
function movementModal(id){if(!state.products.length)throw Error('Primero registra un artículo.');modal('Registrar movimiento',`<form id="movement-form"><div class="form-grid"><div class="field full"><label for="product-select">Artículo</label><select id="product-select" name="productId">${state.products.slice().sort((a,b)=>a.name.localeCompare(b.name,'es')).map(p=>`<option value="${p.id}" ${id===p.id?'selected':''}>${esc(p.sku)} · ${esc(p.name)} · Quedan ${quantity(p.stock)}</option>`).join('')}</select></div><div class="field"><label for="move-type">Tipo de movimiento</label><select id="move-type" name="type"><option>Entrada</option><option>Salida / ajuste</option></select></div>${field('Cantidad','quantity','','text','inputmode="decimal" required')}<div class="field full"><label for="move-note">Motivo o referencia</label><input id="move-note" name="note" placeholder="Ej.: compra al proveedor, factura 125" maxlength="1000" required></div></div><p class="receipt-note">La salida / ajuste resta mercancía sin registrar una venta. Úsala para pérdidas, deterioros o correcciones justificadas.</p><div class="modal-actions"><button class="btn primary">Guardar movimiento</button></div></form>`);$('#movement-form').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));try{await commit('movement',{...f,quantity:numberInput(f.quantity,1000)});$('#modal').close();toast('Movimiento guardado.');}catch(e){formError(e);}};}
async function submitSale(event){event.preventDefault();if(busy||pendingSale)return;try{for(const input of event.target.querySelectorAll('[data-cart]')){const amount=numberInput(input.value,1000);cart.find(item=>item.productId===input.dataset.cart).quantity=amount;}const form=Object.fromEntries(new FormData(event.target)),total=cartTotal(),data=buildSaleData({form,cart,products:state.products,total,numberInput});const operation=newOp('sale',data);applyOperation(state,operation);busy=true;$('#sale-form button[type=submit]').disabled=true;if(primary()){local=await localOperation(operation);state=local.state;cart=[];saleDraft={documentType:'sale',customer:'',customerPhone:'',customerIdNumber:'',paid:'',method:'Efectivo'};$('#sale-form')?.reset();busy=false;render();receiptModal(operation.id);toast('Comprobante guardado. Existencias descontadas.');void tick();}else{if(!available)throw Error('La PC está desconectada.');pendingSale={id:operation.id,data};localStorage.setItem(pendingStorageKey,JSON.stringify(pendingSale));await api('sale',pendingSale);busy=false;render();void checkPending();}}catch(error){busy=false;if(pendingSale&&error.status&&error.status<500){pendingSale=null;localStorage.removeItem(pendingStorageKey);}toast(error.message,true);render();}}
async function checkPending(){if(!pendingSale||primary())return;try{const r=await fetch('/api/inventory?storeId='+encodeURIComponent(storeId)+'&command='+encodeURIComponent(pendingSale.id),{cache:'no-store'});if(!r.ok)return;const j=await r.json();if(['completed','rejected','expired'].includes(j.status)){const id=pendingSale.id;pendingSale=null;localStorage.removeItem(pendingStorageKey);if(j.status==='completed'){cart=[];saleDraft={documentType:'sale',customer:'',customerPhone:'',customerIdNumber:'',paid:'',method:'Efectivo'};$('#sale-form')?.reset();await refreshMobile();render();receiptModal(id);toast('Venta confirmada por la PC.');}else{toast(j.result?.error||'La venta no se realizó.',true);render();}}else if(j.status==='missing'){try{await api('sale',pendingSale);}catch(e){if(e.status&&e.status<500){pendingSale=null;localStorage.removeItem(pendingStorageKey);toast('La venta no se registró. '+e.message,true);render();}else throw e;}}}catch{available=false;}}
function receiptHtml(s){const f=saleAccounting(s,state),collections=(state.collections||[]).filter(item=>item.saleId===s.id),refunds=f.refunds;return `<h3>${s.documentType==='sale'?'Comprobante de venta':'Factura comercial interna'}</h3><div class="receipt-title"><div><h3>${esc(s.shop.name)}</h3><small>${esc(s.shop.rnc?s.shop.rnc+' · ':'')}${esc(s.shop.phone)}</small><p>${esc(s.shop.address)}</p></div><strong>${esc(s.number)}</strong></div><p>${at(s.at)} · ${esc(s.customer)}<br>${s.customerPhone?`Teléfono: ${esc(s.customerPhone)} · `:''}${s.customerIdNumber?`ID: ${esc(s.customerIdNumber)}<br>`:''}${esc(f.status)} · Pago inicial: ${esc(s.method)}</p><div class="table-scroll"><table><thead><tr><th>Artículo</th><th class="numeric">Cantidad</th><th class="numeric">Precio</th><th class="numeric">Importe</th></tr></thead><tbody>${s.items.map(item=>`<tr><td><strong>${esc(item.name)}</strong><small>${esc(item.sku)}</small></td><td class="numeric">${quantity(item.quantity)}</td><td class="numeric">${money(item.unitCents)}</td><td class="numeric">${money(item.totalCents)}</td></tr>`).join('')}</tbody></table></div><div class="receipt-totals">Total original: <strong>${money(s.totalCents)}</strong><br>Cobrado al emitir: ${money(f.receivedInitiallyCents)}<br>Cambio entregado: ${money(s.changeCents)}<br>Cobros posteriores: ${money(f.collectedLaterCents)}<br>Mercancía devuelta: ${money(f.amountCents)}<br>Dinero reembolsado: ${money(f.cashRefundCents)}<br>Venta neta: <strong>${money(f.netRevenueCents)}</strong><br>Saldo pendiente: <strong>${money(f.balanceCents)}</strong></div>${collections.length?`<h4>Pagos posteriores</h4><ul>${collections.map(item=>`<li>${at(item.at)} · ${esc(item.method)} · ${money(item.amountCents)}${item.note?` · ${esc(item.note)}`:''}</li>`).join('')}</ul>`:''}${refunds.length?`<h4>Devoluciones</h4><ul>${refunds.map(item=>`<li>${at(item.at)} · ${money(item.amountCents)} devueltos · ${money(item.cashRefundCents||0)} entregados en dinero · ${esc(item.note||'')}</li>`).join('')}</ul>`:''}<p class="receipt-note">${s.documentType==='sale'?'Comprobante interno de venta':'Factura comercial interna'}. No es un comprobante fiscal y no incluye NCF, e-CF ni ITBIS.</p>`;}
function receiptModal(id){const sale=state.sales.find(item=>item.id===id);if(!sale)return;const financials=saleAccounting(sale,state),canReturn=!financials.returnedAll;modal((sale.documentType==='sale'?'Venta normal ':'Factura a nombre de cliente ')+esc(sale.number),receiptHtml(sale)+`<div class="modal-actions">${financials.balanceCents>0&&primary()?btn('Registrar cobro',`collect:${id}`,''):''}${canReturn&&primary()?btn('Devolver artículos',`refund:${id}`,'danger')+btn('Anular factura completa',`void:${id}`,'danger'):''}<button class="btn" id="download-pdf-btn">Descargar PDF</button><button class="btn primary" id="print-btn">Imprimir / guardar como PDF</button></div>`);$('#download-pdf-btn').onclick=()=>downloadReceiptPdf(sale);$('#print-btn').onclick=()=>{$('#print-receipt').innerHTML=receiptHtml(sale);window.print();};$('#modal').querySelectorAll('[data-action]').forEach(button=>button.onclick=()=>{const [action,id]=button.dataset.action.split(':');$('#modal').close();if(action==='collect')collectionModal(id);else if(action==='refund')refundModal(id);else if(action==='void')voidModal(id);});}
function collectionModal(saleId){const sale=state.sales.find(item=>item.id===saleId);if(!sale)return;const current=saleAccounting(sale,state);if(current.balanceCents<=0)throw Error('Esta factura no tiene saldo pendiente.');modal('Registrar cobro · '+esc(sale.number),`<p class="setup-note">Saldo pendiente: <strong>${money(current.balanceCents)}</strong>. El cobro quedará agregado al historial y al cierre de caja.</p><form id="collection-form"><div class="form-grid"><div class="field full"><label for="collection-amount">Importe recibido · RD$</label><input id="collection-amount" name="amount" type="number" min="0.01" max="${(current.balanceCents/100).toFixed(2)}" step="0.01" value="${(current.balanceCents/100).toFixed(2)}" required></div><div class="field full"><label for="collection-method">Forma de pago</label><select id="collection-method" name="method"><option>Efectivo</option><option>Transferencia</option><option>Tarjeta</option><option>Otro</option></select></div><div class="field full"><label for="collection-note">Nota o referencia (opcional)</label><input id="collection-note" name="note" maxlength="500"></div></div><div class="modal-actions"><button class="btn primary">Guardar cobro</button></div></form>`);$('#collection-form').onsubmit=async event=>{event.preventDefault();const form=Object.fromEntries(new FormData(event.target));try{await commit('collection',{saleId,amountCents:numberInput(form.amount),method:form.method,note:form.note});$('#modal').close();toast('Cobro registrado y saldo actualizado.');}catch(error){formError(error);}};}
function refundModal(saleId){const sale=state.sales.find(item=>item.id===saleId);if(!sale)return;const summary=saleRefundSummary(sale,state),available=sale.items.map(item=>({...item,remaining:item.quantity-(summary.refundedByProduct.get(item.productId)||0)})).filter(item=>item.remaining>0);if(!available.length)throw Error('La cantidad completa de esta factura ya fue devuelta.');const balance=saleAccounting(sale,state).balanceCents;modal('Registrar devolución · '+esc(sale.number),`<p class="setup-note">El importe de la devolución se calcula desde los precios y cantidades originales. Primero reduce el saldo pendiente; solo el excedente se registra como dinero reembolsado.</p><div class="refund-lines">${available.map(item=>`<div class="refund-line"><div><strong>${esc(item.name)}</strong><small>Facturado: ${quantity(item.quantity)} · Aún devolvible: ${quantity(item.remaining)} · ${money(item.unitCents)} por unidad</small></div><label>Cantidad<input data-refund-quantity="${esc(item.productId)}" type="number" min="0" max="${item.remaining/1000}" step="0.001" value="0"></label><label class="refund-restock"><input data-refund-restock="${esc(item.productId)}" type="checkbox" checked> Reintegrar a existencias</label></div>`).join('')}</div><div class="refund-preview"><div><span>Importe de la devolución</span><strong id="refund-value">RD$ 0.00</strong></div><div><span>Reducción del saldo pendiente</span><strong id="refund-credit">RD$ 0.00</strong></div><div><span>Dinero a entregar al cliente</span><strong id="refund-cash">RD$ 0.00</strong></div></div><div class="form-grid"><div class="field"><label for="refund-method">Forma de reembolso</label><select id="refund-method" name="method"><option>Efectivo</option><option>Transferencia</option><option>Tarjeta</option><option>Otro</option></select></div><div class="field"><label for="refund-note">Motivo / referencia</label><input id="refund-note" name="note" maxlength="1000" required></div></div><p class="receipt-note">Los artículos marcados para reintegrar volverán a las existencias; los demás quedan como merma o producto no revendible.</p><div class="modal-actions"><button class="btn danger" id="submit-refund" disabled>Guardar devolución</button></div>`);
 const preview=()=>{let amount=0;try{for(const line of available){const input=$(`[data-refund-quantity="${CSS.escape(line.productId)}"]`),quantityBack=input.value?numberInput(input.value,1000):0;if(quantityBack>line.remaining)throw Error(`La cantidad supera lo que queda por devolver de ${line.name}.`);const previous=summary.refundedByProduct.get(line.productId)||0;amount+=Math.round(line.totalCents*(previous+quantityBack)/line.quantity)-Math.round(line.totalCents*previous/line.quantity);}const cash=Math.max(0,amount-balance),credit=amount-cash;$('#refund-value').textContent=money(amount);$('#refund-credit').textContent=money(credit);$('#refund-cash').textContent=money(cash);$('#submit-refund').disabled=!available.some(line=>Number($(`[data-refund-quantity=\"${CSS.escape(line.productId)}\"]`).value)>0)||!$('#refund-note').value.trim();$('#form-error').hidden=true;}catch(error){$('#submit-refund').disabled=true;formError(error);}};
 $('#modal').querySelectorAll('[data-refund-quantity],[data-refund-restock],#refund-note').forEach(input=>input.addEventListener('input',preview));$('#modal').querySelectorAll('[data-refund-restock]').forEach(input=>input.addEventListener('change',preview));
 $('#submit-refund').onclick=async event=>{event.preventDefault();const rows=[];try{for(const line of available){const value=$(`[data-refund-quantity="${CSS.escape(line.productId)}"]`).value,quantityBack=value?numberInput(value,1000):0;if(quantityBack>0)rows.push({productId:line.productId,quantity:quantityBack,restock:$(`[data-refund-restock="${CSS.escape(line.productId)}"]`).checked});}await commit('refund',{saleId,items:rows,method:$('#refund-method').value,note:$('#refund-note').value});$('#modal').close();toast('Devolución guardada. Se actualizaron saldo y existencias.');}catch(error){formError(error);}};
}
async function downloadReceiptPdf(s){try{let demoSale=s;if(demo){const f=saleAccounting(s,state);demoSale={...s,status:f.status,netSalesCents:f.netRevenueCents,collectedLaterCents:f.collectedLaterCents,refundCents:f.amountCents,cashRefundedCents:f.cashRefundCents,balanceCents:f.balanceCents,collections:(state.collections||[]).filter(item=>item.saleId===s.id),refunds:(state.refunds||[]).filter(item=>item.saleId===s.id)};}const response=await fetch('/api/inventory/receipt',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(demo?{demo:true,storeId,sale:demoSale}:{storeId,receiptId:s.id})});if(!response.ok){let problem={};try{problem=await response.json();}catch{}throw Error(problem.error||'No se pudo preparar el PDF. Sincroniza la venta e inténtalo otra vez.');}const blob=await response.blob(),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`${s.number}.pdf`;link.click();setTimeout(()=>URL.revokeObjectURL(url),30000);toast('PDF descargado.');}catch(error){toast(error.message,true);}}
function voidModal(id){const sale=state.sales.find(item=>item.id===id);modal('Anular '+esc(sale.number),`<p class="setup-note">Se registrará la devolución de todas las cantidades aún no devueltas. El dinero pendiente de pago se cancela primero; solo el resto se devuelve al cliente. Indica el motivo y cómo se reembolsa el efectivo.</p><form id="void-form"><div class="form-grid"><div class="field full"><label for="void-method">Forma de reembolso</label><select id="void-method" name="method"><option>Efectivo</option><option>Transferencia</option><option>Tarjeta</option><option>Otro</option></select></div><div class="field full"><label for="void-note">Motivo</label><input id="void-note" name="note" maxlength="1000" required></div></div><div class="modal-actions"><button class="btn danger">Anular factura y devolver mercancía</button></div></form>`);$('#void-form').onsubmit=async event=>{event.preventDefault();try{const form=Object.fromEntries(new FormData(event.target));await commit('void',{saleId:id,note:form.note,method:form.method});$('#modal').close();toast('Factura anulada y saldo, dinero y mercancía actualizados.');}catch(error){formError(error);}};}
function download(content,name,type){const link=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
async function backup(){if(!primary())throw Error('El respaldo completo se descarga desde la PC principal.');local=await readLocal();download(JSON.stringify({...local,storeId,storeName:storeProfile.name,exportedAt:new Date().toISOString()},null,2),`Mi-tienda-${storeProfile.slug}-respaldo-${day(Date.now())}.json`,'application/json');local=await changeLocal(x=>({...x,backupAt:new Date().toISOString()}));toast('Respaldo descargado. Guárdalo fuera de esta computadora.');if(view==='settings')render();}
$('#backup-btn').onclick=()=>backup().catch(e=>toast(e.message,true));
$('#restore-file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>8*1024*1024)throw Error('El respaldo supera 8 MB.');const data=JSON.parse(await file.text());if((data.storeId||defaultStoreId)!==storeId)throw Error('Este respaldo pertenece a otro perfil de tienda. Cambia al perfil correspondiente antes de recuperarlo.');validateState(data.state);if(!ownerId)throw Error('Entra a tu cuenta antes de recuperar el respaldo.');await api('register',{deviceId:data.deviceId});local=await restoreEmptyBackup(data,ownerId);deviceId=local.deviceId;localStorage.setItem('mi-tienda-device',deviceId);state=local.state;role='primary';render();await tick(true);toast('Respaldo recuperado.');}catch(e){toast(e.message,true);}e.target.value='';};
const csvCell=v=>{let s=String(v??'');if(/^[=+@-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};
function exportCsv(){const rows=[['codigo','nombre','precio','costo','existencia','minimo','categoria','codigo_barras'],...state.products.map(p=>[p.sku,p.name,(p.unitCents/100).toFixed(2),(p.costCents/100).toFixed(2),p.stock/1000,p.minStock/1000,p.category,p.barcode])];download('\uFEFF'+rows.map(r=>r.map(csvCell).join(',')).join('\n'),`Inventario-${day(Date.now())}.csv`,'text/csv;charset=utf-8');}
function exportAccountingCsv(){const from=reportFrom||'1900-01-01',to=reportTo||day(Date.now()),within=value=>{const key=day(value);return key>=from&&key<=to;},rows=[['fecha','documento_interno','cliente','tipo','importe_facturado_rd$','entrada_o_salida_rd$','forma','nota']];for(const sale of state.sales){if(within(sale.at))rows.push([day(sale.at),sale.number,sale.customer,sale.documentType==='sale'?'Venta normal':'Factura a nombre de cliente', (sale.totalCents/100).toFixed(2),((sale.paidCents-sale.changeCents)/100).toFixed(2),sale.method,'Emisión de factura']);}for(const payment of state.collections||[]){if(!within(payment.at))continue;const sale=state.sales.find(item=>item.id===payment.saleId);rows.push([day(payment.at),sale?.number||'',sale?.customer||'','Cobro posterior','0.00',(payment.amountCents/100).toFixed(2),payment.method,payment.note||'']);}for(const refund of state.refunds||[]){if(!within(refund.at))continue;const sale=state.sales.find(item=>item.id===refund.saleId);rows.push([day(refund.at),sale?.number||'',sale?.customer||'','Devolución',(-refund.amountCents/100).toFixed(2),(-refund.cashRefundCents/100).toFixed(2),refund.method,refund.note]);}for(const sale of state.sales){if(sale.status==='Anulada'&&!(state.refunds||[]).some(refund=>refund.saleId===sale.id)&&within(sale.voidAt||sale.at))rows.push([day(sale.voidAt||sale.at),sale.number,sale.customer,'Devolución histórica',(-sale.totalCents/100).toFixed(2),(-((sale.paidCents-sale.changeCents)/100)).toFixed(2),sale.method,sale.voidReason||'Anulación anterior']);}const summary=accountingSummary(state,reportFrom,reportTo);rows.push([],['CIERRE DEL PERÍODO','','','Resumen', (summary.netSalesCents/100).toFixed(2),(summary.netCashCents/100).toFixed(2),'',`Bruto ${(summary.grossSalesCents/100).toFixed(2)}; devoluciones ${(summary.refundCents/100).toFixed(2)}; por cobrar ${(summary.receivableCents/100).toFixed(2)}; costo neto ${(summary.netCostOfGoodsCents/100).toFixed(2)}; utilidad bruta ${(summary.grossProfitCents/100).toFixed(2)}`]);download('\uFEFF'+rows.map(row=>row.map(csvCell).join(',')).join('\n'),`Libro-facturacion-${from}-${to}.csv`,'text/csv;charset=utf-8');toast('Libro del período descargado.');}
function parseCsv(text){text=text.replace(/^\uFEFF/,'');const delimiter=text.split(/\r?\n/)[0].includes(';')?';':',';let quoted=false,cell='',row=[],rows=[];for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(c===delimiter&&!quoted){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(v=>v.trim()))rows.push(row);row=[];cell='';}else cell+=c;}if(quoted)throw Error('El CSV tiene comillas sin cerrar.');row.push(cell);if(row.some(v=>v.trim()))rows.push(row);return rows;}
function importModal(){modal('Importar artículos',`<p class="setup-note">Agrega tu catálogo completo desde Excel: guarda la hoja como CSV UTF-8. La importación es conjunta; si una fila tiene errores, no se guarda ninguna.</p><div class="file-zone"><strong>Columnas requeridas</strong><p>codigo, nombre, precio, costo, existencia, minimo, categoria, codigo_barras</p><p>Precio y costo en pesos. Cantidades hasta 3 decimales. La existencia del archivo se usa solo para artículos nuevos.</p></div><p class="setup-note">Los códigos que ya existan se rechazan. Para reponer mercancía, registra una entrada.</p><div class="modal-actions"><button class="btn" id="template-btn">Descargar plantilla</button><button class="btn primary" id="choose-csv">Elegir archivo CSV</button></div>`);$('#template-btn').onclick=()=>download('\uFEFFcodigo,nombre,precio,costo,existencia,minimo,categoria,codigo_barras\nART-001,Articulo de ejemplo,150.00,100.00,20,5,General,\n','Plantilla-inventario.csv','text/csv;charset=utf-8');$('#choose-csv').onclick=()=>$('#csv-file').click();}
$('#csv-file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>5*1024*1024)throw Error('El CSV supera 5 MB.');const rows=parseCsv(await file.text()),headers=rows.shift().map(h=>h.trim().toLowerCase());for(const h of ['codigo','nombre','precio','existencia'])if(!headers.includes(h))throw Error('Falta la columna '+h);const products=rows.map((row,i)=>{const f=Object.fromEntries(headers.map((h,j)=>[h,row[j]?.trim()||'']));if(state.products.some(p=>p.sku.toLowerCase()===f.codigo.toLowerCase()))throw Error(`Fila ${i+2}: el código ${f.codigo} ya existe.`);try{return {id:crypto.randomUUID(),sku:f.codigo,name:f.nombre,unitCents:numberInput(f.precio),costCents:numberInput(f.costo||'0'),stock:numberInput(f.existencia,1000),minStock:numberInput(f.minimo||'0',1000),category:f.categoria,barcode:f.codigo_barras};}catch(error){throw Error(`Fila ${i+2}: ${error.message}`);}});await commit('import',{products});$('#modal').close();go('inventory');toast(`Se importaron ${products.length} artículos.`);}catch(error){if($('#form-error'))formError(error);else toast(error.message,true);}e.target.value='';};
async function refreshMobile(){const r=await fetch('/api/inventory?storeId='+encodeURIComponent(storeId)+'&version='+state.version,{cache:'no-store'});const j=await r.json();if(!r.ok)throw Error(j.error||'No se pudo consultar.');ownerId=j.ownerId;cloud={...cloud,...j.primary};available=Boolean(j.primary?.available);if(j.primary?.state)state=validateState(j.primary.state);lastError='';return j;}
async function tick(manual=false){if(ticking||demo)return;const beforeVersion=state.version,beforeAvailable=available;ticking=true;try{if(primary()){
   const current=await readLocal();const uploaded=current.state.version>current.uploadedVersion?current.state:undefined;
   const j=await api('sync',{deviceId,state:uploaded});local=await markUploaded(j.version,j.syncedAt);state=local.state;lastError='';available=true;
   for(const c of j.commands||[]){try{local=await localOperation(c.payload);state=local.state;await api('sync',{deviceId,state:local.state,poll:false});await api('ack',{deviceId,id:c.id});local=await markUploaded(local.state.version,new Date().toISOString());}catch(e){if(!local?.state.sales.some(s=>s.id===c.id)){await api('ack',{deviceId,id:c.id,error:e.message});}else throw e;}}
 }else if(role==='mobile'){await refreshMobile();await checkPending();}
 if(manual)toast('Información actualizada.');
 }catch(e){lastError=e.status===401?'La sesión del servidor venció. Inicia sesión para reanudar la sincronización.':e.message;available=false;if(manual)toast(lastError,true);}finally{ticking=false;if((manual||beforeVersion!==state.version||beforeAvailable!==available)&&!$('#modal').open&&!$('#sale-form input:focus')&&!$('#settings-form input:focus')&&!$('#inventory-search:focus')&&!$('#sale-search:focus')&&!$('#sales-search:focus')&&!$('#movements-search:focus'))render();else status();}}
async function boot(){try{
 local=forceMobile?null:await readLocal();if(local){pendingSale=null;deviceId=local.deviceId;state=validateState(local.state);ownerId=local.ownerId;role='primary';render();}
 if(demo){ownerId='demo';local=local||await initializePrimary('demo',deviceId,storeProfile.name);state=local.state;role='primary';if(isLegacyDemo(state)){local=await changeLocal(old=>({...old,state:initialState(),uploadedVersion:-1,lastSync:null}));state=local.state;}if(state.version===0){local=await changeLocal(old=>({...old,state:{...old.state,shop:{...old.state.shop,name:storeProfile.name}}}));state=local.state;const catalog=createDemoCatalog(storeProfile);local=await localOperation(newOp('import',{products:catalog}));state=local.state;for(const op of createDemoSales(catalog)){local=await localOperation(op);state=local.state;}}if(demoFixtureNeedsShopName(state,storeProfile)){const normalized=structuredClone(state);normalized.shop.name=storeProfile.name;for(const sale of normalized.sales)sale.shop.name=storeProfile.name;local=await changeLocal(old=>({...old,state:normalized}));state=local.state;}render();}
 else{try{const j=await api();ownerId=j.ownerId;cloud=j.primary;if(local&&local.ownerId!==ownerId)throw Error('La cuenta no corresponde a la copia local.');if(local&&cloud?.deviceId!==deviceId){role='none';throw Error('La PC principal registrada no coincide con este equipo.');}if(local&&cloud?.state&&cloud.version>local.state.version){role='none';throw Error('El respaldo local es anterior a la nube. Recupera la copia completa antes de vender.');}if(!local&&cloud?.deviceId===deviceId&&!cloud.state&&!forceMobile){local=await initializePrimary(ownerId,deviceId,storeProfile.name);state=local.state;role='primary';}else if(!local&&cloud){role='mobile';state=cloud.state||initialState();if(state.version===0)state.shop.name=storeProfile.name;available=cloud.available;}lastError='';}catch(e){lastError=e.message;}}
 if('serviceWorker'in navigator){try{await navigator.serviceWorker.register('/inventory-sw.js',{scope:'/'});await navigator.serviceWorker.ready;swReady=true;}catch{swReady=false;}}
 render();if(!demo)await tick();setInterval(()=>void tick(),3000);window.addEventListener('online',()=>void tick());window.addEventListener('offline',()=>{available=false;lastError='Sin conexión. La PC conserva las operaciones para enviarlas cuando vuelva internet.';status();if(!primary())render();});
 }catch(e){$('#main').innerHTML=heading('No se pudo abrir la copia local','Conserva los datos del navegador y revisa el respaldo.')+`<div class="error-text">${esc(e.message)}</div>`;}}
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close();});
void boot();

